import{_ as e,o as s,c as o,a0 as t}from"./chunks/framework.DCluYYrN.js";const h=JSON.parse('{"title":"搶救開機迴圈","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/rescue-from-bootloop.md","filePath":"zh_TW/guide/rescue-from-bootloop.md"}'),l={name:"zh_TW/guide/rescue-from-bootloop.md"};function n(i,a,p,d,r,c){return s(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="intruduction" tabindex="-1">搶救開機迴圈 <a class="header-anchor" href="#intruduction" aria-label="Permalink to &quot;搶救開機迴圈 {#intruduction}&quot;">​</a></h1><p>在寫入裝置時，我們很可能會遇到裝置「變磚」的狀況，從理論上講，如果您只是使用 Fastboot 寫入 Boot 分區或者安裝不合適的模組導致裝置無法開機，那麼這都可以透過合適的作業還原您的手機；這個文件提供一些緊急方法可以讓您在「變磚」中還原。</p><h2 id="brick-by-flashing-boot-partition" tabindex="-1">寫入 Boot 時變磚 <a class="header-anchor" href="#brick-by-flashing-boot-partition" aria-label="Permalink to &quot;寫入 Boot 時變磚 {#brick-by-flashing-boot-partition}&quot;">​</a></h2><p>在 KernelSU 中，寫入 boot 時變磚有下列原因：</p><ol><li>你寫入了錯誤格式的 Boot 映像。比如您的手機 Boot 格式為 <code>gz</code>，但您寫入 <code>lz4</code> 格式的映像，那麼此時手機將無法開機。</li><li>您的手機需要關閉 AVB 驗證才可正常開機 (這通常需要抹除手機上的所有資料)。</li><li>您的核心存在某些錯誤或您的核心並不適合這部手機寫入。</li></ol><p>無論哪種狀況，您都可以透過<strong>寫入原廠 Boot</strong> 還原；因此，在安裝教學最開始，我們已經強烈建議大家，在寫入之前備份自己的原廠 Boot！如果您沒有備份，那麼您可以透過其他與您相同裝置的使用者或官方韌體擷取 Boot。</p><h2 id="brick-by-modules" tabindex="-1">安裝模組變磚 <a class="header-anchor" href="#brick-by-modules" aria-label="Permalink to &quot;安裝模組變磚 {#brick-by-modules}&quot;">​</a></h2><p>安裝模組變磚可能是大家遇到的更常見的狀況，但是這裡要嚴正警示大家：<strong>不要安裝未知來源的模組！！</strong>。因為模組擁有 Root 權限，它能完全對您的裝置造成無法復原的損壞！</p><h3 id="normal-modules" tabindex="-1">一般模組 <a class="header-anchor" href="#normal-modules" aria-label="Permalink to &quot;一般模組 {#normal-modules}&quot;">​</a></h3><p>如果大家安裝了某些開放原始碼的或者被證明是安全的模組使手機無法開機，那麼這種狀況在 KernelSU 中非常容易還原，也無需擔心。KernelSU 內建了安全模式來搶救您的裝置：</p><h4 id="volume-down" tabindex="-1">透過按下「音量 -」搶救 <a class="header-anchor" href="#volume-down" aria-label="Permalink to &quot;透過按下「音量 -」搶救 {#volume-down}&quot;">​</a></h4><p>您可以嘗試使用<strong>安全模式</strong>來搶救。進入安全模式之後，所有的模組將會被停用。</p><p>進入安全模式的方法有兩種：</p><ol><li>某些系統內建的安全模式：有些系統是長按「音量 -」，有些系統 (例如 MIUI/HyperOS) 可以在 Recovery 中啟用安全模式。進入系統的安全模式後，KernelSU 也會進入安全模式，並自動停用模組。</li><li>KernelSU 內建的安全模式：開機第一個畫面後，<strong>連續按下「音量 -」按鈕超過三次</strong>。注意是按下-抬起、按下-抬起、按下-抬起，並非一直按下。</li></ol><p>進入安全模式後，KernelSU 管理員的模組頁面的所有模組將會被停用，但您可以執行「解除安裝」作業，將可能存在問題的模組解除安裝。</p><p>內建的安全模式在核心中實作，因此不會出現按鍵活動無法攔截的狀況。不過對於非 GKI 核心，可能需要手動整合程式碼，可以參閱官方文件指南。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU 在核心模組初始化時註冊音量鍵監聽（LKM 模式下在核心執行 init 行程的時候載入），到 <code>on_post_fs_data</code> 階段時（開機動畫前）註銷。您需要把握好時機並在開機第一個畫面後快速按下「音量 -」按鈕三次。如果裝置啟動速度快或操作不即時，可能無法觸發安全模式。</p><p>如果模組在 initrc 中編寫了不合理的程式碼導致裝置無法開機，即使在安全模式下這些程式碼仍然會執行。</p></div><h4 id="manual-rescue" tabindex="-1">手動救磚 <a class="header-anchor" href="#manual-rescue" aria-label="Permalink to &quot;手動救磚 {#manual-rescue}&quot;">​</a></h4><p>當安全模式無法解決問題時，可以嘗試手動救磚。根據裝置狀態選擇以下方法。</p><p><strong>方法一：透過 ADB 使用 ksud 管理模組</strong></p><p>如果裝置能透過 ADB 獲取 root shell，可以直接使用 <code>ksud</code> 命令列來停用或解除安裝問題模組：</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>掛載 <code>metadata</code> 和 <code>data</code> 分區後，您可以在 Recovery 模式下執行 <code>/data/adb/ksud</code> 指令來管理模組。</p><p>由於 GKI 裝置共用 <code>init</code>，因此 Recovery 模式下仍會載入 KernelSU 核心模組，您應該可以正常使用 <code>ksud</code> 的大部分功能（如設定 feature）。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>adb shell</span></span>
<span class="line"><span>su</span></span>
<span class="line"><span>ksud module list          # 列出所有模組</span></span>
<span class="line"><span>ksud module disable &lt;id&gt;  # 停用問題模組</span></span>
<span class="line"><span>ksud module uninstall &lt;id&gt; # 或直接解除安裝</span></span>
<span class="line"><span>reboot</span></span></code></pre></div><p><strong>方法二：透過 Recovery 手動清理</strong></p><p>如果無法進入系統（連 ADB 都無法連線），需要裝置有第三方 Recovery（如 TWRP）。</p><p>KernelSU 的模組載入依賴核心側的 init.rc 注入檔案和使用者態的 ksud 行程。刪除這些檔案後重新啟動，KernelSU 將不會載入任何模組。</p><p><strong>操作步驟：</strong></p><ol><li>進入 Recovery（如 TWRP）。</li><li>掛載 data 分區：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /data</span></span></code></pre></div>（您可能需要先解密 data 分區。具體操作取決於裝置和解密方式。）</li><li>刪除 ksud，阻止模組載入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f /data/adb/ksud</span></span></code></pre></div></li><li>（可選）掛載 metadata 分區並刪除模組產生的 init.rc 注入檔案：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount /metadata</span></span>
<span class="line"><span>rm -f /metadata/ksu/modules.rc</span></span>
<span class="line"><span>rm -f /metadata/watchdog/ksu/modules.rc</span></span></code></pre></div></li><li>重新啟動裝置：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div></li></ol><p>重新啟動後 KernelSU 將跳過所有模組的載入。進入系統後，即可重新打開 KernelSU 管理員處理模組的問題。</p><h3 id="malicious-modules" tabindex="-1">格式化資料或其他惡意模組 <a class="header-anchor" href="#malicious-modules" aria-label="Permalink to &quot;格式化資料或其他惡意模組 {#malicious-modules}&quot;">​</a></h3><p>如果以上方法無法搶救您的裝置，那麼很可能您安裝的模組存在惡意作業或透過其他方式損壞了您的裝置，在這種狀況下，只有兩個建議：</p><ol><li>抹除資料並完全恢復為官方系統。</li><li>諮詢售後服務。</li></ol>`,32)])])}const m=e(l,[["render",n]]);export{h as __pageData,m as default};
